const body = $json.body ?? $json;
const data = body.data ?? {};
const key = data.key ?? {};

if (key.fromMe === true) return [];

const remoteJid = key.remoteJid ?? data.remoteJid ?? body.remoteJid ?? '';
if (!remoteJid || String(remoteJid).includes('@g.us')) return [];

const message = data.message ?? {};
const text = message.conversation
  ?? message.extendedTextMessage?.text
  ?? message.imageMessage?.caption
  ?? message.videoMessage?.caption
  ?? data.message?.text
  ?? '';

if (!String(text).trim()) return [];

const instanceName = body.instance ?? body.instanceName ?? data.instance ?? '';
const phone = String(remoteJid).split('@')[0].replace(/\D/g, '');

if (!instanceName || !phone) return [];

return [{ json: { instance_name: String(instanceName), phone, user_message: String(text).trim(), remote_jid: String(remoteJid), event: body.event ?? '' } }];

const context = $json;
const incoming = $('Normalize Evolution Message').first().json;
return [{ json: { ...incoming, context, session_key: context.session_key ?? `${incoming.instance_name}:${incoming.phone}`, agent_prompt: `USER MESSAGE:
${incoming.user_message}

AUTHORIZED CONTEXT JSON:
${JSON.stringify(context)}` } }];
